// Package biz — Happ crypto-link helper.
//
// Happ's documented one-tap-import deeplink is `happ://crypt5/<encrypted-payload>`,
// generated by their official crypto service at https://crypto.happ.su/api-v2.php.
// (The community-invented `happ://add/<base64>` scheme is NOT supported by Happ
// and manifests as "URL подписки не валидна" on Mobile clients.)
//
// We call the API once per user, cache the result in users.happ_crypt_link,
// and serve it forever (subscribe_token is stable, encrypted link doesn't
// rotate). Failures fall back to the plain subscription URL — the user can
// still copy-paste it manually.
package biz

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"time"

	"github.com/heyearth/backend/internal/db"
)

const happCryptoEndpoint = "https://crypto.happ.su/api-v2.php"

// GetOrFetchHappCryptLink returns the cached happ://crypt5/ deeplink for the
// user, fetching from crypto.happ.su if missing.
//
// subscribeUrl is the plain HTTPS subscription URL (e.g.
// "https://hiearth.ru/api/v1/user/subscribe/<token>").
//
// Returns empty string + error if the crypto service is unavailable AND no
// cached value exists — callers should fall back to the plain URL.
func GetOrFetchHappCryptLink(userID, subscribeUrl string) (string, error) {
	// Try cache first.
	var cached *string
	err := db.DB.QueryRow(`
		SELECT happ_crypt_link FROM users WHERE user_id = $1
	`, userID).Scan(&cached)
	if err == nil && cached != nil && *cached != "" {
		return *cached, nil
	}

	// Fetch from crypto.happ.su.
	link, err := fetchHappCryptLink(subscribeUrl)
	if err != nil {
		log.Printf("[happ-crypto] fetch for user=%s: %v", userID, err)
		return "", err
	}

	// Cache for next time. Ignore UPDATE errors (we already have the result).
	_, _ = db.DB.Exec(`UPDATE users SET happ_crypt_link = $1 WHERE user_id = $2`, link, userID)

	return link, nil
}

// InvalidateHappCryptLink clears the cached happ link for a user.
// Use when the subscribe_token rotates (rare).
func InvalidateHappCryptLink(userID string) error {
	_, err := db.DB.Exec(`UPDATE users SET happ_crypt_link = NULL WHERE user_id = $1`, userID)
	return err
}

// fetchHappCryptLink does a single POST to crypto.happ.su/api-v2.php and parses
// the JSON response {"encrypted_link": "happ://crypt5/..."}.
func fetchHappCryptLink(subscribeUrl string) (string, error) {
	body, err := json.Marshal(map[string]string{"url": subscribeUrl})
	if err != nil {
		return "", fmt.Errorf("marshal req: %w", err)
	}

	client := &http.Client{Timeout: 10 * time.Second}
	req, err := http.NewRequest(http.MethodPost, happCryptoEndpoint, bytes.NewReader(body))
	if err != nil {
		return "", fmt.Errorf("new req: %w", err)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Accept", "application/json")

	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("post: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		raw, _ := io.ReadAll(io.LimitReader(resp.Body, 1024))
		return "", fmt.Errorf("crypto.happ.su HTTP %d: %s", resp.StatusCode, string(raw))
	}

	var out struct {
		EncryptedLink string `json:"encrypted_link"`
		Error         string `json:"error,omitempty"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
		return "", fmt.Errorf("decode resp: %w", err)
	}
	if out.Error != "" {
		return "", fmt.Errorf("crypto.happ.su error: %s", out.Error)
	}
	if out.EncryptedLink == "" {
		return "", fmt.Errorf("crypto.happ.su returned empty link")
	}
	return out.EncryptedLink, nil
}
